<template>
  <div class="schedule-wrapper">
    <div
      ref="scheduleRef"
      class="schedule unselectable"
      :class="`zoom-level-${zoomLevel}`"
    >
      <div
        ref="entityListRef"
        class="entities"
        @mousedown="startBrowsingY"
        @touchstart="startBrowsingY"
        v-show="!hideEntities"
      >
        <div
          class="total-man-days"
          :class="{
            'without-milestones': !withMilestones
          }"
        >
          <div class="actions">
            <button
              class="button is-small is-link"
              :title="$t('main.expand_all')"
              @click="$emit('expand-all')"
              v-if="showExpandAll"
            >
              <list-chevrons-up-down-icon :size="15" />
            </button>
          </div>
          <span class="total-value" v-if="!hideManDays">
            {{ formatDuration(totalManDays) }} {{ durationUnit }}
          </span>
        </div>

        <div
          class="entity-name-list"
          :class="{
            'without-milestones': !withMilestones
          }"
        >
          <div
            :key="`entity-${rootElement.id}`"
            class="timeline-element"
            v-for="rootElement in hierarchy"
          >
            <div
              class="entity-line entity-name flexrow root"
              :class="{
                expanded: rootElement.expanded
              }"
              :style="entityLineStyle(rootElement, true, true)"
              v-show="!hideRoot"
            >
              <span
                class="expand flexrow-item"
                :style="{
                  color: isDarkTheme ? '#EEE' : '#999',
                  'margin-top': '4px'
                }"
                role="button"
                tabindex="0"
                @click="expandRootElement(rootElement)"
                @keydown.enter.prevent="expandRootElement(rootElement)"
                @keydown.space.prevent="expandRootElement(rootElement)"
              >
                <chevron-right-icon v-if="!rootElement.expanded" />
                <chevron-down-icon v-else />
              </span>
              <span class="avatar flexrow-item" v-if="rootElement.avatar">
                <production-name
                  :production="rootElement"
                  :only-avatar="true"
                  :size="30"
                  v-if="rootElement.type === 'Project'"
                />
                <people-avatar
                  :person="rootElement"
                  :is-link="false"
                  :font-size="14"
                  :size="28"
                  v-else
                />
              </span>
              <span
                class="filler flexrow-item root-element-name ellipsis"
                :style="{
                  'border-left': rootElement.avatar
                    ? null
                    : `4px solid ${rootElement.color}`
                }"
                :title="rootElement.name"
              >
                {{ rootElement.name }}
              </span>
              <department-name
                class="ml05"
                :department="departmentMap.get(departmentId)"
                :key="departmentId"
                no-padding
                only-dot
                v-for="departmentId in rootElement.departments"
              />
              <router-link
                class="root-element-link flexrow-item"
                :title="rootElement.name"
                :to="rootElement.route"
                v-if="rootElement.route"
              >
                <link-icon :size="12" />
              </router-link>
              <input
                class="man-day-input flexrow-item mr1"
                type="number"
                step="any"
                placeholder="0"
                @input="
                  $emit('estimation-changed', {
                    estimation: durationToMinutes(
                      organisation,
                      $event.target.valueAsNumber || 0
                    ),
                    item: rootElement,
                    daysOff: rootElement.daysOff
                  })
                "
                v-if="
                  !rootElement.avatar && rootElement.editable && !hideManDays
                "
                :value="formatDuration(rootElement.man_days, false)"
              />
              <span
                class="man-days-unit flexrow-item"
                v-if="
                  !rootElement.avatar && rootElement.editable && !hideManDays
                "
              >
                {{ durationUnit }}
              </span>
              <span
                class="man-days-unit flexrow-item"
                v-if="
                  (rootElement.avatar || !rootElement.editable) && !hideManDays
                "
              >
                {{ formatDuration(rootElement.man_days) }}
                {{ durationUnit }}
              </span>
            </div>

            <div
              class="children"
              :class="{ mb0: hideRoot }"
              :style="childrenStyle(rootElement, multiline, true)"
              v-if="rootElement.expanded"
            >
              <div class="children-loader" v-if="rootElement.loading">
                <spinner class="child-spinner" :size="20" />
              </div>
              <template v-else-if="subchildren">
                <div
                  :key="childElement.id"
                  :style="childNameStyle(rootElement, index)"
                  class="child"
                  v-for="(childElement, index) in rootElement.children"
                >
                  <div class="child-name">
                    <span
                      class="entity-line entity-name child-line"
                      style="background: none"
                    >
                      <span class="filler">
                        {{ childElement.name }}
                      </span>
                    </span>
                  </div>
                  <div
                    :key="personId"
                    v-for="[personId] in childElement.children"
                    :style="{
                      height: `${40 * getNbLines(childElement.children.get(personId))}px`
                    }"
                    class="subchild-label"
                  >
                    <people-avatar
                      :person="rootElement.people[personId]"
                      :is-link="false"
                      :font-size="14"
                      :size="28"
                    />
                    {{ rootElement.people[personId].full_name }}
                  </div>
                </div>
              </template>
              <template v-else-if="!multiline">
                <div
                  class="child-name"
                  :key="`entity-${childElement.id}`"
                  v-for="(childElement, j) in rootElement.children"
                >
                  <div
                    class="entity-line entity-name child-line flexrow"
                    :style="childNameStyle(rootElement, j)"
                  >
                    <router-link
                      class="filler flexrow-item child-element-name ellipsis-2-lines"
                      :title="childElement.name"
                      :to="childElement.route"
                      v-if="childElement.route"
                    >
                      {{ childElement.name }}
                    </router-link>
                    <span
                      class="filler flexrow-item ellipsis-2-lines"
                      :title="childElement.name"
                      v-else
                    >
                      {{ childElement.name }}
                    </span>
                    <span
                      class="flexrow flexrow-item man-days-unit-wrapper"
                      v-if="childElement.editable && !hideManDays"
                    >
                      <input
                        class="flexrow-item man-days-unit"
                        type="number"
                        min="0"
                        placeholder="0"
                        step="any"
                        @input="
                          onChildEstimationChanged(
                            $event,
                            childElement,
                            rootElement
                          )
                        "
                        :value="formatDuration(childElement.man_days, false)"
                      />
                      {{ durationUnit }}
                    </span>
                    <span class="man-days-unit flexrow-item" v-else>
                      {{ formatDuration(childElement.man_days) }}
                      {{ durationUnit }}
                    </span>
                  </div>
                </div>
              </template>
            </div>
          </div>
        </div>
      </div>

      <div class="timeline" ref="timelineRef">
        <div
          ref="timelineHeaderRef"
          class="timeline-header"
          :class="{
            'without-milestones': !withMilestones
          }"
          @mousedown="startBrowsingX"
          @touchstart="startBrowsingX"
          v-if="zoomLevel > 0"
        >
          <div
            class="day"
            :class="{
              'without-milestones': !withMilestones,
              'new-week': day.newWeek
            }"
            :key="`header-${day.text}-${index}`"
            v-for="(day, index) in daysAvailable"
          >
            <div
              class="milestone pointer"
              role="button"
              tabindex="0"
              @click="showEditMilestoneModal(day, currentMilestones[day.text])"
              @keydown.enter.prevent="
                showEditMilestoneModal(day, currentMilestones[day.text])
              "
              @keydown.space.prevent="
                showEditMilestoneModal(day, currentMilestones[day.text])
              "
              v-if="currentMilestones[day.text] && withMilestones"
            >
              <div class="milestone-tooltip">
                {{ currentMilestones[day.text].name }}
              </div>
              <div class="bull">&bull;</div>
            </div>
            <div class="milestone" v-else-if="withMilestones">
              <div class="bull">&nbsp;</div>
            </div>

            <div
              :class="{
                'with-milestones':
                  withMilestones && isCurrentUserProductionManager,
                'date-widget': true
              }"
            >
              <div class="date-name">
                <span class="month-name" v-if="day.newMonth">
                  {{ day.monthText }}
                </span>
                <span class="week-number" v-if="day.newWeek">
                  {{ day.weekNumber }}
                </span>
                <div :class="dayClass(day, index)">
                  <span v-if="zoomLevel > 2"> {{ day.dayText }} / </span>
                  <span class="day-number">
                    <briefcase-icon
                      class="day-off-icon"
                      :size="14"
                      v-if="day.off"
                    />
                    {{ day.dayNumber }}
                  </span>
                </div>
              </div>
              <div
                class="add-milestone"
                :title="addMilestoneTitle(day)"
                role="button"
                tabindex="0"
                @click="
                  showEditMilestoneModal(day, currentMilestones[day.text])
                "
                @keydown.enter.prevent="
                  showEditMilestoneModal(day, currentMilestones[day.text])
                "
                @keydown.space.prevent="
                  showEditMilestoneModal(day, currentMilestones[day.text])
                "
                v-if="withMilestones && isCurrentUserProductionManager"
              >
                <span class="button">
                  <edit-icon :size="10" v-if="currentMilestones[day.text]" />
                  <plus-icon :size="12" :stroke-width="3" v-else />
                </span>
              </div>
            </div>
          </div>
        </div>

        <div
          ref="timelineHeaderRef"
          class="timeline-header"
          :class="{
            'without-milestones': !withMilestones
          }"
          @mousedown="startBrowsingX"
          @touchstart="startBrowsingX"
          v-else
        >
          <div
            class="day week"
            :class="{
              'without-milestones': !withMilestones
            }"
            :key="`header-${week.weekText}-${index}`"
            :title="week.label"
            v-for="(week, index) in weeksAvailable"
          >
            <div
              :class="{
                'hidden-milestones': withMilestones
              }"
            >
              <div class="date-name">
                <span class="month-name" v-if="week.newMonth">
                  {{ week.monthText }}
                </span>
                <span class="week-number"> &nbsp; </span>
                <div :class="dayClass(week, index)">
                  <span class="day-number">
                    {{ week.weekNumber }}
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div
          ref="timelineContentWrapperRef"
          class="timeline-content-wrapper"
          @mousemove.passive="onPositionBarMove"
          @scroll.passive="onTimelineScroll"
        >
          <div
            ref="timelineContentRef"
            class="timeline-content"
            :style="timelineStyle"
            @mousedown="startBrowsing"
            @touchstart="startBrowsing"
          >
            <div
              ref="timelineSubStartRef"
              class="sub-zone"
              :style="timelineSubStartStyle"
              v-if="subStartDate"
            ></div>

            <div
              ref="timelineSubEndRef"
              class="sub-zone"
              :style="timelineSubEndStyle"
              v-if="subEndDate"
            ></div>

            <div
              ref="timelineTodayPositionRef"
              class="timeline-position today"
              :style="timelineTodayPositionStyle"
            ></div>
            <div
              ref="timelinePositionRef"
              class="timeline-position"
              :style="timelinePositionStyle"
              v-show="!isChangeDates"
            ></div>
            <template v-if="withMilestones && !isWeekMode">
              <div
                class="milestone-vertical-line"
                :style="milestoneLineStyle(milestone)"
                :key="`milestone-${milestone.date}`"
                v-for="milestone in Object.values(currentMilestones)"
              ></div>
            </template>
            <div
              class="timeline-element"
              :data-id="rootElement.id"
              :key="`entity-line-${rootElement.id}`"
              v-for="rootElement in hierarchy"
            >
              <div
                class="day-off"
                :class="{
                  'day-off-sub-zone':
                    subStartDate?.diff(dayOff.date, 'days') > 0 ||
                    subEndDate?.diff(dayOff.date, 'days') < 0
                }"
                :key="`dayoff-${dayOff.id}-${index}`"
                :style="dayOffStyle(dayOff)"
                :title="dayOff.description"
                v-for="(dayOff, index) in cachedDayOffRange(
                  rootElement.daysOff
                )"
              >
                <briefcase-icon class="day-off-icon" :size="14" />
              </div>
              <div
                class="entity-line root-element"
                :style="entityLineStyle(rootElement, true)"
                @dragenter="onRootDragEnter($event, rootElement)"
                @dragleave="onRootDragLeave($event, rootElement)"
                v-show="!hideRoot"
              >
                <div
                  class="timebar-wrapper"
                  :class="{
                    thinner: multiline
                  }"
                  :title="`${rootElement.name} (${displayDate(rootElement.startDate)} - ${displayDate(rootElement.endDate)})`"
                  :style="timebarStyle(rootElement, true)"
                >
                  <div
                    class="timebar"
                    v-show="isVisible(rootElement)"
                    role="button"
                    tabindex="0"
                    @click="onRootBarClick(rootElement)"
                    @keydown.enter.prevent="
                      $emit('root-element-selected', rootElement)
                    "
                    v-if="rootElement.editable"
                  >
                    <div
                      class="timebar-left-hand"
                      @mousedown="moveTimebarLeftSide(rootElement, $event)"
                      @touchstart="moveTimebarLeftSide(rootElement, $event)"
                    ></div>
                    <div
                      class="timebar-center"
                      @mousedown="moveTimebar(rootElement, $event)"
                      @touchstart="moveTimebar(rootElement, $event)"
                    ></div>
                    <div
                      class="timebar-right-hand"
                      @mousedown="moveTimebarRightSide(rootElement, $event)"
                      @touchstart="moveTimebarRightSide(rootElement, $event)"
                    ></div>
                  </div>
                </div>
              </div>

              <div
                class="children children-loading"
                :style="childrenStyle(rootElement, multiline)"
                v-if="rootElement.expanded && rootElement.loading"
              >
                <div class="children-loader">
                  <spinner class="child-spinner" :size="20" />
                </div>
              </div>

              <div
                class="children"
                :class="{ 'drop-item-target': reassignable && multiline }"
                :data-root-element-id="rootElement.id"
                :style="childrenStyle(rootElement, multiline)"
                v-else-if="rootElement.expanded"
                @dragenter="onTaskDragEnter($event, rootElement)"
                @dragover="onTaskDragOver($event, rootElement)"
                @dragleave="onTaskDragLeave"
                @drop="onTaskDrop($event, rootElement)"
              >
                <div
                  class="entity-line child-line hidden"
                  v-if="invertLinesColor"
                >
                  <!-- to invert odd/event line color -->
                </div>
                <template
                  v-if="
                    dropTarget.rootElementId === rootElement.id &&
                    !dropTarget.forbidden
                  "
                >
                  <div
                    class="drop-ghost"
                    :key="`drop-ghost-${segment.id}`"
                    :style="{
                      left: `${segment.left}px`,
                      width: `${segment.width}px`,
                      '--timebar-color': segment.color || undefined
                    }"
                    v-for="segment in dropTarget.segments"
                  ></div>
                </template>
                <div
                  class="drop-forbidden"
                  v-if="
                    dropTarget.rootElementId === rootElement.id &&
                    dropTarget.forbidden
                  "
                >
                  <span
                    class="drop-forbidden-message"
                    :style="{ left: `${dropTarget.messageLeft + 16}px` }"
                  >
                    <ban-icon :size="14" />
                    {{ $t(`schedule.drop_forbidden_${dropTarget.forbidden}`) }}
                  </span>
                </div>
                <div
                  class="entity-line child-line"
                  :class="{ multiline }"
                  :key="`entity-line-${childElement.id}`"
                  :style="{
                    ...(multiline && timelineMultilineStyle(childElement)),
                    ...(subchildren && timelineSubchildrenStyle(childElement))
                  }"
                  v-for="childElement in rootElement.children"
                  v-show="!rootElement.loading"
                >
                  <template v-if="withStatuses">
                    <span
                      class="status-date status-date-wip"
                      :class="{
                        'status-date-gap':
                          childElement.real_start_date.slice(0, 10) ===
                            childElement.end_date?.slice(0, 10) ||
                          childElement.real_start_date.slice(0, 10) ===
                            childElement.done_date?.slice(0, 10)
                      }"
                      :style="dateStatusStyle(childElement.real_start_date)"
                      :title="statuses.wip.name"
                      v-if="childElement.real_start_date"
                    >
                    </span>
                    <span
                      class="status-date status-date-wfa"
                      :class="{
                        'status-date-gap':
                          childElement.end_date.slice(0, 10) ===
                            childElement.real_start_date?.slice(0, 10) ||
                          childElement.end_date.slice(0, 10) ===
                            childElement.done_date?.slice(0, 10)
                      }"
                      :style="dateStatusStyle(childElement.end_date)"
                      :title="statuses.wfa.name"
                      v-if="childElement.end_date"
                    >
                    </span>
                    <span
                      class="status-date status-date-done"
                      :class="{
                        'status-date-gap':
                          childElement.done_date.slice(0, 10) ===
                            childElement.real_start_date?.slice(0, 10) ||
                          childElement.done_date.slice(0, 10) ===
                            childElement.end_date?.slice(0, 10)
                      }"
                      :style="dateStatusStyle(childElement.done_date)"
                      :title="statuses.done.name"
                      v-if="childElement.done_date"
                    >
                    </span>
                  </template>

                  <template v-if="withTimesheets && rootElement.timesheet">
                    <div
                      class="timesheet"
                      :style="
                        timesheetStyle(
                          timesheet,
                          childElement,
                          rootElement,
                          withEstimations
                        )
                      "
                      :title="`${formatDuration(timesheet.duration)} ${isDurationInHours ? $t('main.hours_spent', { count: formatDuration(timesheet.duration, false) }) : $t('main.days_spent', { count: formatDuration(timesheet.duration, false) })}`"
                      :key="timesheet.id"
                      v-for="timesheet in taskTimesheets(
                        rootElement,
                        childElement.id
                      )"
                    ></div>
                  </template>

                  <div
                    class="timebar timebar-ghost timebar-ghost-before"
                    :title="`${childElement.previousElement.name} (${displayDate(childElement.previousElement.startDate)} - ${displayDate(childElement.previousElement.endDate)})`"
                    :class="{
                      'with-timesheets': withTimesheets
                    }"
                    :style="
                      timebarChildStyle(
                        childElement.previousElement,
                        rootElement,
                        multiline,
                        50
                      )
                    "
                    v-if="withGhosts && childElement.previousElement"
                  ></div>

                  <div
                    class="timebar timebar-ghost timebar-ghost-after"
                    :title="`${childElement.nextElement.name} (${displayDate(childElement.nextElement.startDate)} - ${displayDate(childElement.nextElement.endDate)})`"
                    :class="{
                      'with-timesheets': withTimesheets
                    }"
                    :style="
                      timebarChildStyle(
                        childElement.nextElement,
                        rootElement,
                        multiline,
                        50
                      )
                    "
                    v-if="withGhosts && childElement.nextElement"
                  ></div>

                  <div
                    class="timebar"
                    :class="{
                      selected: isSelected(childElement),
                      'timebar-subchildren': subchildren,
                      'with-timesheets': withTimesheets,
                      invalid: isOverlapping(childElement)
                    }"
                    :title="`${multiline && childElement.project_name ? `${childElement.project_name} - ` : ''}${childElement.name} (${displayDate(childElement.startDate)} - ${displayDate(childElement.endDate)})`"
                    :style="
                      timebarChildStyle(
                        childElement,
                        rootElement,
                        multiline,
                        withTimesheets && 25,
                        isDarkTheme ? 'black' : 'white'
                      )
                    "
                    v-show="subchildren || isVisible(childElement)"
                    role="button"
                    tabindex="0"
                    @click="onChildBarClick(rootElement, childElement)"
                    @keydown.enter.prevent="
                      $emit('item-selected', rootElement, childElement)
                    "
                    v-if="withEstimations"
                  >
                    <div
                      class="timebar-left-hand"
                      @mousedown="moveTimebarLeftSide(childElement, $event)"
                      @touchstart="moveTimebarLeftSide(childElement, $event)"
                      v-if="
                        !isChangeDates &&
                        selection.length === 1 &&
                        isSelected(childElement) &&
                        childElement.editable &&
                        !childElement.unresizable
                      "
                    ></div>
                    <div
                      class="timebar-center"
                      :class="{
                        ellipsis: multiline || subchildren,
                        'has-text-centered': subchildren
                      }"
                      @mousedown="moveTimebar(childElement, $event)"
                      @touchstart="moveTimebar(childElement, $event)"
                    >
                      <template v-if="multiline && childElement.project_name">
                        <b>{{ childElement.project_name }}</b>
                        <br />
                      </template>
                      <template v-if="multiline || subchildren">
                        {{ childElement.name }}
                      </template>
                    </div>
                    <div
                      class="timebar-right-hand"
                      @mousedown="moveTimebarRightSide(childElement, $event)"
                      @touchstart="moveTimebarRightSide(childElement, $event)"
                      v-if="
                        !isChangeDates &&
                        selection.length === 1 &&
                        isSelected(childElement) &&
                        childElement.editable &&
                        !childElement.unresizable
                      "
                    ></div>
                  </div>

                  <div
                    v-if="subchildren && childElement.children.size"
                    class="subchildren"
                  >
                    <div
                      :key="personId"
                      v-for="[personId, subchild] in childElement.children"
                      :style="{
                        height: `${40 * getNbLines(subchild)}px`
                      }"
                      class="subchild"
                      :class="{ 'drop-item-target': reassignable }"
                      :data-entity-type-id="childElement.object_id"
                      :data-person-id="personId"
                    >
                      <div
                        class="day-off"
                        :key="`dayoff-${dayOff.id}-${index}`"
                        :style="dayOffStyle(dayOff)"
                        :title="dayOff.description"
                        v-for="(dayOff, index) in cachedDayOffRange(
                          rootElement.people[personId].daysOff
                        )"
                      >
                        <briefcase-icon class="day-off-icon" :size="14" />
                      </div>
                      <div
                        class="timebar"
                        :class="{ selected: isSelected(task) }"
                        :key="index"
                        :style="timebarSubchildStyle(task, rootElement)"
                        :title="timebarSubchildTitle(task)"
                        v-for="(task, index) in subchild"
                      >
                        <div
                          class="timebar-left-hand"
                          @mousedown="moveTimebarLeftSide(task, $event)"
                          @touchstart="moveTimebarLeftSide(task, $event)"
                          v-if="
                            !isChangeDates &&
                            selection.length === 1 &&
                            isSelected(task) &&
                            task.editable &&
                            !task.unresizable
                          "
                        ></div>
                        <div
                          class="timebar-center ellipsis"
                          role="button"
                          tabindex="0"
                          @mousedown="moveTimebar(task, $event)"
                          @touchstart="moveTimebar(task, $event)"
                          @click="
                            onTaskBarClick(rootElement, childElement, task)
                          "
                          @keydown.enter.prevent="
                            $emit(
                              'task-selected',
                              rootElement,
                              childElement,
                              task,
                              selection
                            )
                          "
                        >
                          {{ task.entity.name }}
                        </div>
                        <div
                          class="timebar-right-hand"
                          @mousedown="moveTimebarRightSide(task, $event)"
                          @touchstart="moveTimebarRightSide(task, $event)"
                          v-if="
                            !isChangeDates &&
                            selection.length === 1 &&
                            isSelected(task) &&
                            task.editable &&
                            !task.unresizable
                          "
                        ></div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>

    <edit-milestone-modal
      active
      :is-loading="loading.edit"
      :is-error="errors.edit"
      :milestone-to-edit="milestoneToEdit"
      @confirm="confirmEditMilestone"
      @cancel="hideEditMilestoneModal"
      @remove-milestone="removeMilestone"
      v-if="withMilestones && modals.edit"
    />
  </div>
</template>

<script setup>
/*
 * Component to facilitate the build of schedule pages.
 */
import {
  computed,
  nextTick,
  onBeforeUnmount,
  onMounted,
  reactive,
  ref,
  toRaw,
  watch
} from 'vue'
import { useI18n } from 'vue-i18n'
import { useStore } from 'vuex'
import {
  BanIcon,
  BriefcaseIcon,
  ChevronDownIcon,
  ChevronRightIcon,
  EditIcon,
  LinkIcon,
  ListChevronsUpDownIcon,
  PlusIcon
} from 'lucide-vue-next'
import moment from 'moment-timezone'

import colors from '@/lib/colors'
import {
  addBusinessDays,
  daysToMinutes,
  durationToMinutes,
  formatDisplayDate,
  formatFullDate,
  getBusinessDays,
  getDayOffRange,
  minutesToDays,
  parseDate
} from '@/lib/time'

import DepartmentName from '@/components/widgets/DepartmentName.vue'
import EditMilestoneModal from '@/components/modals/EditMilestoneModal.vue'
import PeopleAvatar from '@/components/widgets/PeopleAvatar.vue'
import ProductionName from '@/components/widgets/ProductionName.vue'
import Spinner from '@/components/widgets/Spinner.vue'

const store = useStore()
const { t } = useI18n()

const props = defineProps({
  clipChildren: {
    type: Boolean,
    default: false
  },
  daysOff: {
    type: Array,
    default: () => []
  },
  // page rule (item, person) => reason of the refusal or null, asked after
  // the team check and shown through schedule.drop_forbidden_<reason>
  assignRule: {
    type: Function,
    default: null
  },
  draggedItems: {
    type: Array,
    default: () => []
  },
  endDate: {
    type: Object,
    required: true
  },
  isLoading: {
    type: Boolean,
    default: true
  },
  hideEntities: {
    type: Boolean,
    default: false
  },
  hideManDays: {
    type: Boolean,
    default: false
  },
  hierarchy: {
    default: () => [],
    type: Array
  },
  invertLinesColor: {
    type: Boolean,
    default: false
  },
  showExpandAll: {
    type: Boolean,
    default: false
  },
  subEndDate: {
    type: Object,
    default: null
  },
  subStartDate: {
    type: Object,
    default: null
  },
  startDate: {
    type: Object,
    required: true
  },
  isEstimationLinked: {
    type: Boolean,
    default: false
  },
  withMilestones: {
    type: Boolean,
    default: true
  },
  withEstimations: {
    type: Boolean,
    default: true
  },
  withGhosts: {
    type: Boolean,
    default: false
  },
  withStatuses: {
    type: Boolean,
    default: false
  },
  withTimesheets: {
    type: Boolean,
    default: false
  },
  hideRoot: {
    type: Boolean,
    default: false
  },
  zoomLevel: {
    type: Number,
    default: 2
  },
  multiline: {
    type: Boolean,
    default: false
  },
  subchildren: {
    type: Boolean,
    default: false
  },
  reassignable: {
    type: Boolean,
    default: false
  },
  type: {
    type: String,
    validator: value => ['prev', 'real'].includes(value)
  }
})

const emit = defineEmits([
  'estimation-changed',
  'expand-all',
  'item-assign',
  'item-changed',
  'item-drop',
  'item-selected',
  'item-unassign',
  'root-element-expanded',
  'root-element-selected',
  'scroll',
  'task-selected',
  'task-unselected'
])

// Template refs
const scheduleRef = ref(null)
const entityListRef = ref(null)
const timelineRef = ref(null)
const timelineContentRef = ref(null)
const timelineContentWrapperRef = ref(null)
const timelineHeaderRef = ref(null)
const timelinePositionRef = ref(null)

// Store getters
const currentProduction = computed(() => store.getters.currentProduction)
const dateFormat = computed(() => store.getters.dateFormat)
const departmentMap = computed(() => store.getters.departmentMap)

const displayDate = date => formatDisplayDate(toRaw(date), dateFormat.value)
const isCurrentUserProductionManager = computed(
  () => store.getters.isCurrentUserProductionManager
)
const isDarkTheme = computed(() => store.getters.isDarkTheme)
const milestones = computed(() => store.getters.milestones)
const openProductions = computed(() => store.getters.openProductions)
const organisation = computed(() => store.getters.organisation)
const taskMap = computed(() => store.getters.taskMap)
const taskStatuses = computed(() => store.getters.taskStatuses)

// Format mixin replacements
const isDurationInHours = computed(() => {
  return organisation.value.format_duration_in_hours
})

const durationUnit = computed(() =>
  isDurationInHours.value ? t('schedule.hours') : t('schedule.md')
)

const formatDuration = (minutes, toLocale = true) => {
  if (!minutes) {
    return 0
  }

  const duration = organisation.value.format_duration_in_hours
    ? minutes / 60
    : minutesToDays(organisation.value, minutes)

  if (toLocale) {
    return duration.toLocaleString('fullwide', {
      maximumFractionDigits: 2
    })
  }
  return Math.round(duration * 100) / 100
}

// Dom mixin replacements
const addEvents = events => {
  events.forEach(([type, listener]) => {
    document.addEventListener(type, listener)
  })
}

const removeEvents = events => {
  events.forEach(([type, listener]) => {
    document.removeEventListener(type, listener)
  })
}

const getClientX = event => {
  return (
    event.touches?.[0]?.clientX ??
    event.changedTouches?.[0]?.clientX ??
    event.clientX
  )
}

const getClientY = event => {
  return (
    event.touches?.[0]?.clientY ??
    event.changedTouches?.[0]?.clientY ??
    event.clientY
  )
}

// Store actions
const deleteMilestone = milestone => {
  return store.dispatch('deleteMilestone', milestone)
}

const loadMilestones = production => {
  return store.dispatch('loadMilestones', production)
}

const saveMilestone = milestone => {
  return store.dispatch('saveMilestone', milestone)
}

// Data
const currentElement = ref(null)
const selection = ref([])
const isBrowsingX = ref(false)
const isBrowsingY = ref(false)
const isChangeDates = ref(false)
const isChangeStartDate = ref(false)
const isChangeEndDate = ref(false)
const milestoneToEdit = reactive({
  date: moment()
})
const errors = reactive({
  edit: false
})
const modals = reactive({
  edit: false
})
const loading = reactive({
  edit: false
})

let initialClientX = null
let initialClientY = null
let lastStartDate = null
let lastEndDate = null
// person row the drag started on: a multi-assignee task renders one bar per
// assignee, so assignees[0] is not necessarily the person being reassigned
let dragSourcePersonId = null
// person row each dragged bar last hopped to during the drag: once the bar
// left its source row, the source id is gone from assignees and only this
// map knows which row the next hop must unassign
const dragPersonByItem = new Map()

// a native click still fires on mouseup after a genuine drag (mousedown and
// mouseup landed on the same bar), so an unguarded click handler would
// re-select/expand the row right after every move. stopBrowsing sets this
// once it detects the pointer actually moved; the next click consumes it.
let justDragged = false

// cached wrapper rect: getBoundingClientRect on every mousemove forces a
// layout; invalidated on resize and zoom via resetScheduleSize
let wrapperRect = null

// spring-loading: hovering a collapsed person while dragging a task
// expands the row after a short delay, so its drop zone appears under
// the drag
let expandHoverTimer = null
let expandHoverRootId = null

// external tasks hovering a person row: drives the drop-preview ghost
// bars (allowed, one segment per dragged task) or the crossed-out
// overlay (forbidden)
const dropTarget = reactive({
  forbidden: null,
  messageLeft: 0,
  rootElementId: null,
  segments: []
})
let positionBarFrame = null
let moveFrame = null
let lastMoveEvent = null

let domEvents = []
let moveEvents = []

// Computed

const statuses = computed(() => {
  return {
    wip: taskStatuses.value.find(status => status.is_wip) ?? {},
    wfa: taskStatuses.value.find(status => status.is_feedback_request) ?? {},
    done: taskStatuses.value.find(status => status.is_done) ?? {}
  }
})

const currentMilestones = computed(() => {
  const localMilestones = {}
  Object.keys(milestones.value).forEach(key => {
    if (displayedDaysIndex.value[key]) {
      localMilestones[key] = milestones.value[key]
    }
  })
  return localMilestones
})

const cellWidth = computed(() => {
  const cellWidthByLevel = [20, 20, 40, 60, 120]
  return cellWidthByLevel[props.zoomLevel] || 20
})

const daysAvailable = computed(() => {
  const days = []
  let day = props.startDate.clone().utc().startOf('day')
  const endDate = props.endDate.clone().utc().startOf('day')
  const daysOff = new Set(
    getDayOffRange(props.daysOff).map(dayOff => dayOff.date)
  )

  while (day.isSameOrBefore(endDate)) {
    day.off = daysOff.has(day.toISOString().slice(0, 10))
    day.newWeek = day.isoWeekday() === 1
    day.newMonth = day.date() === 1
    day.weekend = [6, 7].includes(day.isoWeekday())
    day.weekNumber = day.week()
    day.text = day.format('YYYY-MM-DD')
    day.monthText = day.format('MMMM YY')
    day.dayNumber = day.format('DD')
    day.dayText = day.format('ddd')[0]
    days.push(day)
    day = day.clone().add(1, 'days')
  }

  // always show month and week number at start of schedule
  if (days.length) {
    const indexNextMonth = days.findIndex(day => day.newMonth)
    if (indexNextMonth >= 5 || indexNextMonth === -1) {
      days[0].newMonth = true
    }
    const indexNextWeek = days.findIndex(day => day.newWeek)
    if (indexNextWeek === -1) {
      days[0].newWeek = true
    }
  }
  return days
})

const weeksAvailable = computed(() => {
  if (daysAvailable.value.length < 1) return []
  const startDate = daysAvailable.value[0]
  const endDate = daysAvailable.value[daysAvailable.value.length - 1]
  const lastDay = endDate.clone().add(7, 'days')

  const weeks = []
  // first Monday on or after the schedule start
  const monday = startDate.clone().add((8 - startDate.isoWeekday()) % 7, 'days')
  while (monday.isSameOrBefore(lastDay)) {
    const week = monday.clone()
    week.weekText = week.format('YYYY-MM-DD')
    week.label = `${week.weekText} to ${week
      .clone()
      .add(6, 'days')
      .format('YYYY-MM-DD')}`
    week.weekNumber = week.week()
    week.newMonth =
      weeks.length === 0 || week.month() !== weeks[weeks.length - 1].month()
    week.monthText = week.format('MMMM YY')
    weeks.push(week)
    monday.add(7, 'days')
  }
  return weeks
})

const displayedDays = computed(() => {
  return daysAvailable.value
})

const displayedDaysIndex = computed(() => {
  let index = 0
  const dayIndex = {}
  displayedDays.value.forEach(d => {
    dayIndex[d.text] = index
    index++
  })
  return dayIndex
})

const displayedWeeksIndex = computed(() => {
  let index = 0
  const weekIndex = {}
  weeksAvailable.value.forEach(w => {
    weekIndex[w.weekText] = index
    index++
  })
  return weekIndex
})

const isRealSchedule = computed(() => {
  return props.type === 'real'
})

const totalManDays = computed(() => {
  return props.hierarchy.reduce(
    (acc, timeElement) => acc + (timeElement.man_days || 0),
    0
  )
})

// Styles

const timelineStyle = computed(() => {
  const firstDay = daysAvailable.value[0]
  const multiplier = firstDay ? -1 * (firstDay.isoWeekday() - 1) : 0
  return {
    'background-position-x': `${multiplier * cellWidth.value}px`
  }
})

const timelinePositionStyle = computed(() => {
  return { width: `${cellWidth.value}px` }
})

const timelineTodayPositionStyle = computed(() => {
  const today = moment().utc(true)
  return {
    width: `${cellWidth.value}px`,
    left: `${getTimebarLeft({ startDate: today }) - 3}px`,
    display: isInRange(today) ? 'block' : 'none'
  }
})

const timelineSubStartStyle = computed(() => {
  const diff = Math.max(dateDiff(props.startDate, props.subStartDate), 0)
  return {
    left: 0,
    width: `${cellWidth.value * diff}px`
  }
})

const timelineSubEndStyle = computed(() => {
  const diff = Math.max(
    dateDiff(props.subEndDate, props.endDate) - 1, // end date must available
    0
  )
  return {
    right: 0,
    width: `${cellWidth.value * diff}px`
  }
})

const dayAfterEndDate = computed(() => {
  return props.endDate.clone().add(1, 'days')
})

const isWeekMode = computed(() => {
  return props.zoomLevel === 0
})

const unitOfTime = computed(() => {
  return props.zoomLevel > 0 ? 'days' : 'weeks'
})

// Methods
//
// The items keep their moments in reactive state. The helpers below read
// them with toRaw so the clone/diff/format chains stop paying a Proxy trap
// per internal moment field, which leaves only the property read tracked:
// always assign a new moment to an item date (clone first), never mutate
// one in place with add/subtract/startOf, or the bars stop re-rendering.

const getNbLines = (items = []) => {
  const values = items.map(item => item.line || 0)
  return values.length ? Math.max(...values) + 1 : 1
}

const refreshAllItemPositions = () => {
  props.hierarchy.forEach(rootElement => {
    if (rootElement.expanded) {
      refreshItemPositions(rootElement)
    }
  })
}

// Drag-time variant: the collision relayout walks every child of the
// section (moment clones + line scan) and re-renders the moved bars, which
// stalls fast drags on large sections. During a drag a ~100ms cadence is
// enough for live feedback; the drop (stopBrowsing) still runs the exact
// relayout on every moved item.
let lastDragRelayoutAt = 0
const refreshItemPositionsDuringDrag = rootElements => {
  const now = performance.now()
  if (now - lastDragRelayoutAt < 100) return
  lastDragRelayoutAt = now
  rootElements.forEach(refreshItemPositions)
}

const refreshItemPositions = rootElement => {
  if (!rootElement?.children) {
    return
  }

  if (props.multiline) {
    setItemPositions(rootElement.children, unitOfTime.value)
  }

  if (props.subchildren) {
    rootElement.children.forEach(childElement => {
      if (childElement.children) {
        childElement.children.forEach(subchildElement => {
          setItemPositions(subchildElement, unitOfTime.value)
        })
      } else {
        setItemPositions(childElement, unitOfTime.value)
      }
    })
  }
}

const refreshManDays = rootElement => {
  if (props.hideManDays || !rootElement?.children?.length) {
    return
  }

  rootElement.man_days = rootElement.children.reduce(
    (acc, child) => acc + (child.man_days || 0),
    0
  )
}

const isVisible = timeElement => {
  const isStartDateOk = toRaw(timeElement.startDate).isSameOrAfter(
    toRaw(props.startDate)
  )
  const isEndDateOk = toRaw(timeElement.endDate).isSameOrBefore(
    dayAfterEndDate.value
  )
  return isStartDateOk && isEndDateOk
}

const resetScheduleSize = () => {
  wrapperRect = null
  if (timelineContentRef.value) {
    if (props.zoomLevel > 0) {
      timelineContentRef.value.style.width = `${displayedDays.value.length * cellWidth.value}px`
    } else {
      timelineContentRef.value.style.width = `${weeksAvailable.value.length * cellWidth.value}px`
    }
  }
}

const processMouseMove = event => {
  if (isChangeStartDate.value) {
    changeStartDate(event)
  } else if (isChangeEndDate.value) {
    changeEndDate(event)
  } else if (isChangeDates.value) {
    changeDates(event)
  } else {
    if (isBrowsingX.value) scrollScheduleLeft(event)
    if (isBrowsingY.value) scrollScheduleTop(event)
  }
}

// high-frequency mice fire several mousemove events per frame: process only
// the latest one per animation frame
const onMouseMove = event => {
  lastMoveEvent = event
  if (moveFrame) return
  moveFrame = requestAnimationFrame(() => {
    moveFrame = null
    processMouseMove(lastMoveEvent)
  })
}

// document-level move listeners are attached only for the duration of a drag
// or browse: a permanent listener ran on every mousemove of the whole page
const startMoveTracking = () => {
  // a new interaction begins: drop any drag-click flag left armed by a
  // drag whose trailing click never fired (release off the bar, touch
  // drags), otherwise it would swallow this interaction's genuine click
  justDragged = false
  addEvents(moveEvents)
}

const onChildEstimationChanged = (event, childElement, rootElement) => {
  const estimation = durationToMinutes(
    organisation.value,
    event.target.valueAsNumber || 0
  )
  if (props.isEstimationLinked) {
    childElement.man_days = estimation
    childElement.estimation = estimation
    refreshManDays(rootElement)

    if (estimation > 0) {
      childElement.endDate = addBusinessDays(
        childElement.startDate,
        minutesToDays(organisation.value, estimation) - 1,
        rootElement.daysOff
      )
    }
  }
  emit('estimation-changed', {
    taskId: childElement.id,
    estimation,
    item: childElement,
    daysOff: rootElement.daysOff
  })
}

const updatePositionBarPosition = event => {
  if (!timelineContentWrapperRef.value || !timelinePositionRef.value) return

  if (!wrapperRect) {
    wrapperRect = timelineContentWrapperRef.value.getBoundingClientRect()
  }
  const cursorX = getClientX(event) - wrapperRect.left

  if (cursorX <= 0 || cursorX >= wrapperRect.width) return

  const left =
    Math.floor(
      (timelineContentWrapperRef.value.scrollLeft + cursorX) / cellWidth.value
    ) * cellWidth.value
  timelinePositionRef.value.style.left = `${left}px`
}

const onPositionBarMove = event => {
  if (positionBarFrame) return
  positionBarFrame = requestAnimationFrame(() => {
    positionBarFrame = null
    updatePositionBarPosition(event)
  })
}

const isValidItemDates = (startDate, endDate) => {
  return (
    startDate &&
    endDate &&
    startDate.isSameOrAfter(props.startDate.clone().add(-1, 'hour')) &&
    endDate.isSameOrBefore(props.endDate.clone().add(1, 'day')) &&
    startDate.isSameOrBefore(endDate) &&
    endDate.isSameOrAfter(startDate)
  )
}

// dates outside the displayed range (e.g. a task due after the production
// end) resolve to the nearest boundary instead of undefined, which made the
// drag computations crash or silently no-op
const getDisplayedDaysIndex = date => {
  const rawDate = toRaw(date)
  const index = displayedDaysIndex.value[rawDate.format('YYYY-MM-DD')]
  if (index !== undefined) {
    return index
  }
  return rawDate.isBefore(props.startDate) ? 0 : displayedDays.value.length - 1
}

const getDisplayedWeeksIndex = date => {
  // clone before startOf: moment mutates in place and callers pass the
  // items' own dates, which snapped them back to their week's Monday
  const monday = toRaw(date).clone().startOf('isoweek')
  const index = displayedWeeksIndex.value[monday.format('YYYY-MM-DD')]
  if (index !== undefined) {
    return index
  }
  return monday.isBefore(weeksAvailable.value[0])
    ? 0
    : weeksAvailable.value.length - 1
}

const resetDroppableTargets = () => {
  scheduleRef.value?.querySelectorAll('.droppable').forEach(element => {
    element.classList.remove('droppable')
  })
}

const changeDates = event => {
  if (!isSelected(currentElement.value)) {
    // avoid side effect if item unselected
    return
  }

  const change = getClientX(event) - initialClientX - cellWidth.value / 2
  const dayChange = Math.ceil(change / cellWidth.value)

  if (props.reassignable) {
    let target = event.target
    while (target && !target.classList?.contains('drop-item-target')) {
      target = target.parentNode
    }
    if (!target) {
      resetDroppableTargets()
    }
    const currentRootElement = currentElement.value.parentElement
    if (
      props.subchildren &&
      target &&
      target.dataset.personId &&
      target.dataset.entityTypeId &&
      !currentElement.value.assignees?.includes(target.dataset.personId)
    ) {
      // check rights
      if (
        target.dataset.personId === 'unassigned' ||
        target.dataset.entityTypeId !== currentElement.value.entity_type_id
      ) {
        return
      }

      target.classList.add('droppable')

      const newAssigneeId = target.dataset.personId
      selection.value.forEach(item => {
        // multi-selection: an item already on the hovered row would get the
        // assignee id and its bar duplicated
        if (item.assignees.includes(newAssigneeId)) return
        // unassign the row the bar currently sits on: past the first hop the
        // source person is gone from assignees, and the assignees[0]
        // fallback would unassign an untouched co-assignee
        const previousAssigneeId =
          dragPersonByItem.get(item) ??
          (dragSourcePersonId && item.assignees.includes(dragSourcePersonId)
            ? dragSourcePersonId
            : item.assignees[0])

        // the handlers own the assignees and person-line updates: mutating
        // them here too duplicated the new assignee id
        emit('item-unassign', item, previousAssigneeId)
        emit('item-assign', item, newAssigneeId)
        dragPersonByItem.set(item, newAssigneeId)
        refreshItemPositions(currentRootElement)
      })
    } else if (
      !props.subchildren &&
      target &&
      target.dataset.rootElementId &&
      currentRootElement.id !== target.dataset.rootElementId
    ) {
      const newRootElement = props.hierarchy.find(
        rootElement => rootElement.id === target.dataset.rootElementId
      )
      selection.value.forEach(item => {
        if (!checkUserIsAllowed(item, newRootElement)) {
          return
        }
        target.classList.add('droppable')
        // update assignation in element hierarchy
        const previousRootElement = item.parentElement
        item.parentElement = newRootElement
        previousRootElement.children = previousRootElement.children.filter(
          ({ id }) => id !== item.id
        )
        newRootElement.children = newRootElement.children.filter(
          ({ id }) => id !== item.id
        )
        newRootElement.children.push(item)
        emit('item-unassign', item, previousRootElement)
        emit('item-assign', item, newRootElement)
        refreshItemPositions(previousRootElement)
      })
      refreshItemPositions(newRootElement)
    }
  }

  // a bar whose real dates lie outside the displayed range has no exact
  // index: the boundary-resolved index math would compute the move against
  // the window edge and teleport the bar there on the first tick, then the
  // drop would persist the reset dates. Keep such bars unmovable (their
  // dates must be fixed from the task panel first).
  if (
    !isValidItemDates(
      currentElement.value.startDate,
      currentElement.value.endDate
    )
  ) {
    return
  }

  if (lastStartDate.isBefore(props.startDate)) {
    lastStartDate = props.startDate.clone()
  }

  if (lastEndDate.isBefore(props.startDate)) {
    lastEndDate = props.startDate.clone().add(1, 'days')
  }

  const startDate = lastStartDate
  const endDate = lastEndDate
  if (!isWeekMode.value) {
    const startDateIndex = getDisplayedDaysIndex(startDate)
    const endDateIndex = getDisplayedDaysIndex(endDate)
    const length = endDateIndex - startDateIndex
    let currentIndex = getDisplayedDaysIndex(startDate)

    currentIndex += dayChange
    if (currentIndex < 0) currentIndex = 0

    const newStartDate = displayedDays.value[currentIndex]
    if (newStartDate) {
      const newEndDate = displayedDays.value[currentIndex + length]
      const dateDiffVal = newStartDate.diff(currentElement.value.startDate)
      if (dateDiffVal && isValidItemDates(newStartDate, newEndDate)) {
        // update all selected items
        selection.value.forEach(item => {
          item.startDate = item.startDate.clone().add(dateDiffVal)
          item.endDate = item.endDate.clone().add(dateDiffVal)
        })
        selection.value.forEach(item => {
          propagateClipToChildren(item)
        })
        if (props.multiline || props.subchildren) {
          const parentElements = [
            ...new Set(selection.value.map(item => item.parentElement))
          ]
          refreshItemPositionsDuringDrag(parentElements)
        }
      }
    }
  } else {
    const startDateIndex = getDisplayedWeeksIndex(startDate)
    const endDateIndex = getDisplayedWeeksIndex(endDate)
    const length = endDateIndex - startDateIndex
    let currentIndex = getDisplayedWeeksIndex(startDate)
    currentIndex += dayChange
    if (currentIndex < 0) currentIndex = 0
    const newStartDate = weeksAvailable.value[currentIndex]
    if (newStartDate) {
      const newEndDate = weeksAvailable.value[currentIndex + length]
      if (isValidItemDates(newStartDate, newEndDate)) {
        // clone: assigning the weeksAvailable moments directly aliases the
        // header entries with the item dates
        currentElement.value.startDate = newStartDate.clone()
        currentElement.value.endDate = newEndDate.clone()
      }
    }
  }
}

const changeStartDate = event => {
  const change = getClientX(event) - initialClientX + cellWidth.value / 2
  const dayChange = Math.floor(change / cellWidth.value)

  const startDate = lastStartDate
  const endDate = currentElement.value.endDate
  let currentIndex, endDateIndex
  if (isWeekMode.value) {
    currentIndex = getDisplayedWeeksIndex(startDate)
    endDateIndex = getDisplayedWeeksIndex(endDate)
  } else {
    currentIndex = getDisplayedDaysIndex(startDate)
    endDateIndex = getDisplayedDaysIndex(endDate)
  }
  currentIndex += dayChange
  if (currentIndex > endDateIndex) currentIndex = endDateIndex
  if (currentIndex < 0) currentIndex = 0

  const newStartDate = isWeekMode.value
    ? weeksAvailable.value[currentIndex]
    : displayedDays.value[currentIndex]

  if (
    newStartDate &&
    !newStartDate.isSame(currentElement.value.startDate) &&
    isValidItemDates(newStartDate, currentElement.value.endDate)
  ) {
    currentElement.value.startDate = newStartDate.clone()
    updateItemEstimation(currentElement.value)
    propagateClipToChildren(currentElement.value)
    refreshItemPositionsDuringDrag([currentElement.value.parentElement])
    resetSelection([currentElement.value])
  }
}

const changeEndDate = event => {
  const change = getClientX(event) - initialClientX + cellWidth.value / 2
  const dayChange = Math.ceil(change / cellWidth.value)

  if (currentElement.value.startDate.isBefore(props.startDate)) {
    currentElement.value.startDate = props.startDate.clone()
  }

  if (currentElement.value.endDate.isBefore(props.startDate)) {
    currentElement.value.endDate = props.startDate.clone().add(1, 'days')
  }

  if (lastEndDate.isBefore(props.startDate)) {
    lastEndDate = props.startDate.clone().add(1, 'days')
  }

  const startDate = currentElement.value.startDate
  const endDate = lastEndDate
  let startDateIndex, currentIndex
  if (isWeekMode.value) {
    startDateIndex = getDisplayedWeeksIndex(startDate)
    currentIndex = getDisplayedWeeksIndex(endDate)
  } else {
    startDateIndex = getDisplayedDaysIndex(startDate)
    currentIndex = getDisplayedDaysIndex(endDate)
  }

  currentIndex += dayChange - 1
  if (currentIndex < startDateIndex) currentIndex = startDateIndex
  if (isWeekMode.value) {
    if (currentIndex > weeksAvailable.value.length - 1) {
      currentIndex = weeksAvailable.value.length - 1
    }
  } else {
    if (currentIndex > displayedDays.value.length - 1) {
      currentIndex = displayedDays.value.length - 1
    }
  }

  const newEndDate = isWeekMode.value
    ? weeksAvailable.value[currentIndex]
    : displayedDays.value[currentIndex]
  if (
    newEndDate &&
    !newEndDate.isSame(currentElement.value.endDate) &&
    isValidItemDates(currentElement.value.startDate, newEndDate)
  ) {
    currentElement.value.endDate = newEndDate.clone()
    updateItemEstimation(currentElement.value)
    propagateClipToChildren(currentElement.value)
    refreshItemPositionsDuringDrag([currentElement.value.parentElement])
    resetSelection([currentElement.value])
  }
}

// Origin dates (and estimation) are stamped at drag start so the clip can
// restore-then-apply on every tick without drift and a cancelled move can
// restore the exact pre-drag state. Only consumers that opt in through the
// clipChildren prop get the stamping and the propagation: other schedules
// (e.g. MainSchedule) do not persist child moves, so clipping there would
// silently revert on reload.
const stampDragOrigin = timeElement => {
  if (!props.clipChildren) return
  timeElement._dragOrigStartDate = timeElement.startDate.clone()
  timeElement._dragOrigEndDate = timeElement.endDate.clone()
  timeElement._dragOrigEstimation = timeElement.estimation
  if (!timeElement.parentElement && Array.isArray(timeElement.children)) {
    timeElement.children.forEach(child => {
      child._dragOrigStartDate = child.startDate.clone()
      child._dragOrigEndDate = child.endDate.clone()
    })
  }
}

const propagateClipToChildren = item => {
  if (!props.clipChildren) return
  if (item.parentElement || !Array.isArray(item.children)) return
  const newStart = item.startDate
  const newEnd = item.endDate
  item.children.forEach(child => {
    const origStart = child._dragOrigStartDate
    const origEnd = child._dragOrigEndDate
    if (!origStart || !origEnd) return

    // restore from orig before applying clip to prevent drift on back-drag
    child.startDate = origStart.clone()
    child.endDate = origEnd.clone()

    if (origEnd.isSameOrBefore(newStart)) {
      // entirely before new start: snap to 1-day bar at start
      child.startDate = newStart.clone()
      child.endDate = newStart.clone().add(1, 'days')
    } else if (origStart.isBefore(newStart)) {
      // overlaps start: clip start
      child.startDate = newStart.clone()
    } else if (origStart.isSameOrAfter(newEnd)) {
      // entirely after new end: snap to 1-day bar at end
      child.startDate = newEnd.clone().subtract(1, 'days')
      child.endDate = newEnd.clone()
    } else if (origEnd.isAfter(newEnd)) {
      // overlaps end: clip end
      child.endDate = newEnd.clone()
    }
    // else: child fully inside new bounds — already restored, leave untouched
  })
}

const updateItemEstimation = item => {
  if (props.isEstimationLinked) {
    const estimation = getBusinessDays(
      item.startDate,
      item.endDate,
      item.parentElement?.daysOff
    )
    item.estimation = daysToMinutes(organisation.value, estimation)
  }
}

const updateSelection = (item, event) => {
  const isCtrlKey = event.ctrlKey || event.metaKey

  if (isSelected(item)) {
    if (isCtrlKey) {
      removeFromSelection(item)
    }
  } else {
    if (!isCtrlKey) {
      resetSelection()
    }
    addToSelection(item)
  }
}

const isOverlapping = item => {
  return (
    props.withGhosts &&
    ((item.previousElement &&
      toRaw(item.startDate).isSameOrBefore(
        toRaw(item.previousElement.endDate)
      )) ||
      (item.nextElement &&
        toRaw(item.endDate).isSameOrAfter(toRaw(item.nextElement.startDate))))
  )
}

// isSelected runs for every bar on every render: keep it O(1)
const selectedIds = computed(() => new Set(selection.value.map(({ id }) => id)))

const isSelected = item => selectedIds.value.has(item.id)

const addToSelection = itemToAdd => {
  selection.value.push(itemToAdd)
}

const removeFromSelection = itemToRemove => {
  selection.value = selection.value.filter(item => item !== itemToRemove)
}

const resetSelection = value => {
  selection.value = value || []
}

const moveTimebar = (timeElement, event) => {
  event.preventDefault() // avoid scroll of schedule on touch
  if (
    !isChangeStartDate.value &&
    !isChangeEndDate.value &&
    timeElement.editable
  ) {
    isChangeDates.value = true
    isChangeStartDate.value = false
    isChangeEndDate.value = false
    currentElement.value = timeElement
    lastStartDate = timeElement.startDate.clone()
    lastEndDate = timeElement.endDate.clone()
    initialClientX = getClientX(event)
    dragSourcePersonId =
      event.target.closest?.('[data-person-id]')?.dataset.personId ?? null
    dragPersonByItem.clear()
    document.body.style.cursor = props.reassignable ? 'all-scroll' : 'ew-resize'

    startMoveTracking()
    stampDragOrigin(timeElement)
    updateSelection(timeElement, event)
  }
}

const moveTimebarLeftSide = (timeElement, event) => {
  event.preventDefault() // avoid scroll of schedule on touch
  if (!isChangeDates.value && !isChangeEndDate.value && timeElement.editable) {
    isChangeDates.value = false
    isChangeStartDate.value = true
    isChangeEndDate.value = false
    currentElement.value = timeElement
    if (!timeElement.endDate) {
      timeElement.endDate = timeElement.startDate.clone().add(1, 'days')
    }
    lastStartDate = timeElement.startDate.clone()
    lastEndDate = timeElement.endDate.clone()
    initialClientX = getClientX(event)
    document.body.style.cursor = 'w-resize'

    startMoveTracking()
    stampDragOrigin(timeElement)
    updateSelection(timeElement, event)
  }
}

const moveTimebarRightSide = (timeElement, event) => {
  event.preventDefault() // avoid scroll of schedule on touch
  if (
    !isChangeDates.value &&
    !isChangeStartDate.value &&
    timeElement.editable
  ) {
    isChangeDates.value = false
    isChangeStartDate.value = false
    isChangeEndDate.value = true
    currentElement.value = timeElement
    if (!timeElement.endDate) {
      timeElement.endDate = timeElement.startDate.clone().add(1, 'days')
    }
    lastStartDate = timeElement.startDate.clone()
    lastEndDate = timeElement.endDate.clone()
    initialClientX = getClientX(event)
    document.body.style.cursor = 'e-resize'

    startMoveTracking()
    stampDragOrigin(timeElement)
    updateSelection(timeElement, event)
  }
}

const onTimelineScroll = event => {
  if (!event?.target) return
  const position = event.target
  const newTop = position.scrollTop
  entityListRef.value.scrollTop = newTop
  const newLeft = position.scrollLeft
  timelineHeaderRef.value.scrollLeft = newLeft

  emit('scroll', { top: position.scrollTop })
}

const setScrollPosition = top => {
  timelineContentWrapperRef.value.scrollTop = top
  entityListRef.value.scrollTop = top
}

const scrollScheduleLeft = event => {
  if (!timelineContentWrapperRef.value) return
  const previousLeft = timelineContentWrapperRef.value.scrollLeft
  // cumulative delta from the last processed event: movementX would lose the
  // moves skipped by the frame throttle
  const movementX = getClientX(event) - initialClientX
  const newLeft = previousLeft - movementX
  initialClientX = getClientX(event)
  timelineContentWrapperRef.value.scrollLeft = newLeft
  timelineHeaderRef.value.scrollLeft = newLeft
}

const scrollScheduleTop = event => {
  if (!timelineContentWrapperRef.value) return
  const previousTop = timelineContentWrapperRef.value.scrollTop
  const movementY = getClientY(event) - initialClientY
  const newTop = previousTop - movementY
  initialClientY = getClientY(event)
  setScrollPosition(newTop)
}

const scrollToToday = () => {
  scrollToDate(moment().utc(true))
}

// A date out of the range goes to the range end closest to it: doing nothing
// made the Today button look broken.
const scrollToDate = date => {
  setTimeout(() => {
    if (scheduleRef.value) {
      const target = isInRange(date)
        ? date
        : date.isBefore(props.startDate)
          ? props.startDate
          : props.endDate
      const datePosition = getTimebarLeft({ startDate: target }) - 5
      const newLeft = datePosition - (scheduleRef.value.offsetWidth / 2 - 300)
      timelineContentWrapperRef.value.scrollLeft = newLeft
      if (timelineHeaderRef.value) {
        timelineHeaderRef.value.scrollLeft = newLeft
      }
    }
  }, 10)
}

const startBrowsing = event => {
  if (
    !isChangeStartDate.value &&
    !isChangeEndDate.value &&
    !isChangeDates.value
  ) {
    document.body.style.cursor = 'grabbing'
    isBrowsingX.value = true
    isBrowsingY.value = true
    initialClientX = getClientX(event)
    initialClientY = getClientY(event)
    startMoveTracking()
  }
}

const startBrowsingX = event => {
  document.body.style.cursor = 'grabbing'
  isBrowsingX.value = true
  initialClientX = getClientX(event)
  startMoveTracking()
}

const startBrowsingY = event => {
  document.body.style.cursor = 'grabbing'
  isBrowsingY.value = true
  initialClientY = getClientY(event)
  startMoveTracking()
}

const stopBrowsing = event => {
  document.body.style.cursor = 'default'
  removeEvents(moveEvents)
  // a pending frame would move the item again after the drop is saved
  if (moveFrame) {
    cancelAnimationFrame(moveFrame)
    moveFrame = null
  }
  if (currentElement.value) {
    if (initialClientX !== getClientX(event)) {
      justDragged = true
      // on moving or resizing selected items
      selection.value.forEach(item => {
        emit('item-changed', item)
        refreshItemPositions(item.parentElement)
        refreshManDays(item.parentElement)
      })
      // clear selection after moving a single item
      if (isChangeDates.value && selection.value.length === 1) {
        resetSelection()
      }
    } else {
      // reset multi-selection when clicking on a single item
      const isCtrlKey = event.ctrlKey || event.metaKey
      if (isChangeDates.value && selection.value.length > 1 && !isCtrlKey) {
        resetSelection([currentElement.value])
      }
    }
  } else {
    // clear the selection when clicking outside an item
    let target = event.target
    while (target && target !== timelineRef.value) {
      target = target.parentNode
    }
    if (target) {
      resetSelection()
      emit('task-unselected')
    }
  }
  resetDroppableTargets()
  isChangeStartDate.value = false
  isChangeEndDate.value = false
  isChangeDates.value = false
  isBrowsingX.value = false
  isBrowsingY.value = false
  initialClientX = null
  initialClientY = null
  dragSourcePersonId = null
  dragPersonByItem.clear()
  currentElement.value = null
}

// Helpers

// the template iterates day-off ranges for each root and person row on every
// render: expand each daysOff array once and reuse it
const dayOffRangeCache = new WeakMap()
const cachedDayOffRange = daysOff => {
  if (!daysOff?.length) return []
  let range = dayOffRangeCache.get(daysOff)
  if (!range) {
    range = getDayOffRange(daysOff)
    dayOffRangeCache.set(daysOff, range)
  }
  return range
}

// same render-time concern for timesheets: group them by task once per array
const timesheetsByTaskCache = new WeakMap()
const taskTimesheets = (rootElement, taskId) => {
  if (!rootElement.timesheet) return []
  let byTask = timesheetsByTaskCache.get(rootElement.timesheet)
  if (!byTask) {
    byTask = new Map()
    rootElement.timesheet.forEach(timesheet => {
      if (!byTask.has(timesheet.task_id)) {
        byTask.set(timesheet.task_id, [])
      }
      byTask.get(timesheet.task_id).push(timesheet)
    })
    timesheetsByTaskCache.set(rootElement.timesheet, byTask)
  }
  return byTask.get(taskId) ?? []
}

const dateDiff = (startDate, endDate, unit = 'days') => {
  const start = toRaw(startDate)
  const end = toRaw(endDate)
  if (start.isSame(end) || !start.isValid() || !end.isValid()) {
    return 0
  }
  const first = start.clone().utc().startOf('day')
  const last = end.clone().utc().endOf('day')
  return last.diff(first, unit)
}

// Whether the date falls on one of the days the timeline lists, the last one
// included
const isInRange = date => {
  const day = toRaw(date).clone().utc().startOf('day')
  return (
    day.isSameOrAfter(toRaw(props.startDate).clone().utc().startOf('day')) &&
    day.isSameOrBefore(toRaw(props.endDate).clone().utc().startOf('day'))
  )
}

// Styles

const dayClass = (day, index = 0) => {
  return {
    'day-name': true,
    'new-week': day.newWeek || false,
    'new-month': day.newMonth || index === 0 || false,
    weekend: day.weekend || false,
    'day-name-off': day.off || false
  }
}

const dayOffStyle = dayOff => {
  return {
    left: `${getLeftPosition(dayOff.date)}px`,
    width: `${cellWidth.value - 1}px`
  }
}

const dateStatusStyle = date => {
  return {
    left: `${getLeftPosition(date) + cellWidth.value / 2 - 3}px`
  }
}

const getLeftPosition = date => {
  const startDate = moment.utc(date)
  const startDiff = dateDiff(props.startDate, startDate, unitOfTime.value)
  return startDiff * cellWidth.value + 1
}

const entityLineStyle = (
  timeElement,
  root = false,
  header = false,
  expanded = false
) => {
  const style = {}
  let color = timeElement.color
  if (root) {
    // is a person
    color = isDarkTheme.value ? '#222' : '#EEF'
  }
  if (root) {
    style['border-left'] = `1px solid ${color}`
    style['border-top'] = `1px solid ${color}`
    if (!expanded) {
      style['border-bottom'] = `1px solid ${color}`
    }
    if (header) {
      style.background = color
    }
  }
  if (timeElement.expanded) {
    style['margin-bottom'] = '0'
  }
  style['border-left'] = `1px solid ${color}`
  style.color = isDarkTheme.value ? '#EEE' : '#111'
  if (!isDarkTheme.value) {
    style['border-color'] = '#BBE'
  }
  return style
}

const timebarStyle = (timeElement, root = false) => {
  const style = {
    left: `${getTimebarLeft(timeElement)}px`,
    width: `${getTimebarWidth(timeElement)}px`,
    cursor: timeElement.editable
      ? !root && props.reassignable
        ? 'all-scroll'
        : 'ew-resize'
      : 'default'
  }
  if (root) {
    style['background-color'] = timeElement.color
  }
  return style
}

const timelineMultilineStyle = timeElement => {
  return {
    top: `${timeElement.line * 40 + 5}px`,
    left: `${getTimebarLeft(timeElement)}px`
  }
}

const timelineSubchildrenStyle = timeElement => {
  const children = Array.from(timeElement.children.values())
  const nbLines = children.reduce(
    (acc, subChildren) => acc + getNbLines(subChildren),
    0
  )
  const marginBottom = children.length * 10
  return {
    height: `${40 + 40 * nbLines + marginBottom + 2}px`,
    'padding-top': '13px'
  }
}

const timebarChildStyle = (
  timeElement,
  rootElement,
  multiline = false,
  opacityPercentage = 0,
  opacityColor = 'transparent'
) => {
  const elementColor = timeElement.color || rootElement.color
  return {
    left: !multiline && `${getTimebarLeft(timeElement)}px`,
    width: `${getTimebarWidth(timeElement)}px`,
    cursor: timeElement.editable
      ? props.reassignable
        ? 'all-scroll'
        : 'ew-resize'
      : 'default',
    background: opacityPercentage
      ? `color-mix(in srgb, ${elementColor}, ${opacityColor} ${opacityPercentage}%)` // lighter color
      : elementColor
  }
}

const timesheetStyle = (
  timesheet,
  timeElement,
  rootElement,
  withEstimations
) => {
  return {
    top: withEstimations ? '7px' : '18px',
    left: `${getTimebarLeft(timesheet, true)}px`,
    width: `${getTimebarWidth(timesheet)}px`,
    background: timesheet.color || timeElement.color || rootElement.color
  }
}

const timebarSubchildStyle = (timeElement, rootElement) => {
  const color = timeElement.color || rootElement.color
  const selected = isSelected(timeElement)
  return {
    left: `${getTimebarLeft(timeElement)}px`,
    width: `${getTimebarWidth(timeElement)}px`,
    cursor: timeElement.editable
      ? props.reassignable
        ? 'all-scroll'
        : 'ew-resize'
      : 'default',
    top: `${5 + 38 * timeElement.line}px`,
    background: `color-mix(in srgb, ${color} ${selected ? 80 : 40}%, transparent)`,
    'box-shadow': `inset 0 0 1px 2px ${selected ? 'var(--background-selected)' : color}`
  }
}

const timebarSubchildTitle = task => {
  const name = task.entity.name
  const startDate = task.startDate.format('YYYY-MM-DD')
  const endDate = task.endDate.format('YYYY-MM-DD')
  const duration = isRealSchedule.value
    ? formatDuration(task.duration)
    : formatDuration(task.estimation)
  return `${name} (${startDate} - ${endDate}) ${duration} ${durationUnit.value}`
}

// True the first time it's called after a drag, then resets, so it skips
// only that one trailing click and not the next genuine one.
const consumeDragClick = () => {
  if (!justDragged) return false
  justDragged = false
  return true
}

const onRootBarClick = rootElement => {
  if (consumeDragClick()) return
  emit('root-element-selected', rootElement)
}

const onChildBarClick = (rootElement, childElement) => {
  if (consumeDragClick()) return
  emit('item-selected', rootElement, childElement)
}

const onTaskBarClick = (rootElement, childElement, task) => {
  if (consumeDragClick()) return
  emit('task-selected', rootElement, childElement, task, selection.value)
}

const getTimebarLeft = timeElement => {
  const startDate = timeElement.startDate || props.startDate
  const startDiff = dateDiff(props.startDate, startDate, unitOfTime.value)
  return startDiff * cellWidth.value + 3
}

const getTimebarWidth = timeElement => {
  const startDate = toRaw(timeElement.startDate || props.startDate)
  let endDate =
    toRaw(timeElement.endDate) ||
    (timeElement.startDate && startDate.clone().add(1, 'days')) ||
    toRaw(props.startDate).clone().add(1, 'days')

  if (
    timeElement.man_days > 0 &&
    !timeElement.end_date &&
    !timeElement.endDate
  ) {
    const days = Math.ceil(timeElement.man_days)
    endDate = addBusinessDays(startDate, days - 1)
  }

  const lengthDiff = dateDiff(startDate, endDate, unitOfTime.value)
  if (lengthDiff > 0) {
    return (lengthDiff + 1) * cellWidth.value - 6
  } else {
    return cellWidth.value - 4
  }
}

// Children

const expandRootElement = rootElement => {
  if (rootElement.expanded) {
    // clear selected items when collapsing the root element
    selection.value.forEach(item => {
      const taskRootElementId =
        item.parentElement?.parentElement?.id || item.parentElement?.id
      if (taskRootElementId === rootElement.id) {
        removeFromSelection(item)
      }
    })
  }

  emit(
    'root-element-expanded',
    rootElement,
    props.multiline || props.subchildren ? refreshItemPositions : undefined
  )
}

const childNameStyle = (rootElement, index) => {
  const isOdd = index % 2 === 0
  const level = isOdd ? 0.7 : 0.9
  return {
    background: colors.fadeColor(rootElement.color, level)
  }
}

const childrenStyle = (
  rootElement,
  isMultiline = false,
  setBackground = false
) => {
  const style = {
    'border-bottom': `1px solid ${rootElement.color}`,
    'border-left': `1px solid ${rootElement.color}`
  }
  if (isMultiline) {
    const nbLines = getNbLines(rootElement.children)
    style.height = `${40 * nbLines + 10}px`

    if (setBackground) {
      style.background = colors.fadeColor(rootElement.color, 0.7)
    }
  }
  return style
}

